PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL, brand_name TEXT NOT NULL, color TEXT NOT NULL DEFAULT '#2563eb', plan TEXT NOT NULL DEFAULT 'homologacao', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS envelopes(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('DRAFT','SENT','IN_PROGRESS','COMPLETED_TEST','CANCELED')), original_sha256 TEXT NOT NULL, original_key TEXT NOT NULL, size INTEGER NOT NULL, pages INTEGER NOT NULL, ordered INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, expires_at REAL NOT NULL, UNIQUE(org_id,id));
CREATE TABLE IF NOT EXISTS signers(id TEXT PRIMARY KEY, org_id TEXT NOT NULL, envelope_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, position INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONFIRMED_TEST')), confirmed_at TEXT, declared_name TEXT, UNIQUE(org_id,id), UNIQUE(envelope_id,position), UNIQUE(envelope_id,email), FOREIGN KEY(org_id,envelope_id) REFERENCES envelopes(org_id,id));
CREATE TABLE IF NOT EXISTS signing_sessions(token_hash TEXT PRIMARY KEY, org_id TEXT NOT NULL, signer_id TEXT NOT NULL, expires_at REAL NOT NULL, revoked_at TEXT, consumed_at TEXT, FOREIGN KEY(org_id,signer_id) REFERENCES signers(org_id,id));
CREATE TABLE IF NOT EXISTS consents(id TEXT PRIMARY KEY, org_id TEXT NOT NULL, signer_id TEXT NOT NULL, token_hash TEXT NOT NULL REFERENCES signing_sessions(token_hash), terms_version TEXT NOT NULL, terms_sha256 TEXT NOT NULL, terms_text TEXT NOT NULL, accepted_at TEXT NOT NULL, UNIQUE(token_hash), FOREIGN KEY(org_id,signer_id) REFERENCES signers(org_id,id));
CREATE TABLE IF NOT EXISTS audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, org_id TEXT NOT NULL REFERENCES organizations(id), envelope_id TEXT, event_type TEXT NOT NULL, actor TEXT NOT NULL, time_utc TEXT NOT NULL, payload TEXT NOT NULL, prev_event_hash TEXT NOT NULL, event_hash TEXT NOT NULL, FOREIGN KEY(org_id,envelope_id) REFERENCES envelopes(org_id,id));
CREATE INDEX IF NOT EXISTS events_org ON audit_events(org_id,seq);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY, org_id TEXT NOT NULL, envelope_id TEXT NOT NULL UNIQUE, storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(org_id,envelope_id) REFERENCES envelopes(org_id,id));
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY, starts REAL NOT NULL, hits INTEGER NOT NULL);
